/**
 * Uploads Soundarya Lahari (100 verses, Adi Shankaracharya) to
 * shloka_stanzas. Sourced from the web, no user-supplied text. This is the
 * largest upload in this pipeline so far -- sourcing and cross-verification
 * were split across four parallel research passes (verses 1-25, 26-50,
 * 51-75, 76-100), each independently cross-checking multiple sites before
 * this script stitched the results together.
 *
 * The site's metadata declares stanza_count: '100'. Soundarya Lahari is
 * traditionally split into "Ananda Lahari" (verses 1-41, Sri Chakra /
 * Tantric philosophy) and "Soundarya Lahari" proper (verses 42-100,
 * describing the Goddess's physical beauty head to toe). Unlike several
 * other stotras in this pipeline, this text's declared count needed NO
 * reconciliation: every source checked across all four research passes
 * agreed on exactly 100 verses in the same order, and the traditional 41/42
 * section boundary was independently confirmed (manblunder.com's commentary
 * on verse 42 explicitly states the physical-beauty section begins there,
 * and the content lines up cleanly -- verse 41 completes the Sri Chakra
 * sequence, verse 42 opens directly on the Goddess's crown, followed by
 * hair, hairline, face, forehead, eyebrows, eyes, nose, cheeks, lips, teeth,
 * chin, neck, arms, hands, breasts, waist, hips, thighs, knees, feet, and a
 * closing benediction -- anatomically top-down as expected).
 *
 * One genuine appendix situation was found and deliberately excluded:
 * amritanilayam.org labels three further verses (101-103) under an explicit
 * "(अनुबन्धः)" ("appendix") header, separate from the main 100 -- these are
 * NOT included below, matching every other source's placement of a
 * completion colophon immediately after verse 100.
 *
 * Sourcing and cross-checks performed before use (see each verse-range
 * below for specifics): kamakoti.org, vignanam.org, shlokam.org,
 * amritanilayam.org, sa.wikisource.org, stotranidhi.com, manblunder.com,
 * and targeted web-search cross-checks against several more sites where a
 * reading looked suspicious. Real discrepancies found were resolved by
 * majority agreement and/or preferring the reading that parses as
 * grammatically valid Sanskrit over an isolated non-word variant -- this
 * text has more manuscript variation than most in this pipeline, and a
 * meaningful number of real (not just cosmetic) discrepancies turned up:
 *
 * Verses 1-25: cross-checked against shlokam.org, amritanilayam.org, and
 * stotranidhi.com. Verse 1 confirmed against the universally standard
 * opening ("शिवः शक्त्या युक्तो..."). The only real variant found was verse
 * 15's closing word: शलोकम्/stotranidhi both read फणितयः (phaṇitayaḥ) against
 * amritanilayam's बणितयः (with phaṇitayaḥ flagged there as an alternate) --
 * resolved to फणितयः by majority. Verses 9 and 14 carry genuine interpretive
 * uncertainty in their esoteric chakra/tattva gloss (contested among
 * traditional commentators) even though the Sanskrit itself is firm; both
 * are rendered literally rather than picking one commentary's reading.
 *
 * Verses 26-50: cross-checked against sa.wikisource.org and manblunder.com,
 * with a transliteration spot-check for verses 39-40. Ten real discrepancies
 * were resolved toward the grammatically valid / better-attested reading
 * over a non-word variant, e.g. verse 26 विरिञ्चिः (Brahma) over an OCR
 * "विरिश्चि:", verse 31 चतुःषष्ट्या over a garbled "चतुष्ष्ट्या", verse 35
 * बिभृषे (from √भृ) over a व/ब mix-up "विभृषे", verse 40 श्यामं over a
 * mis-split "शयामं". The Ananda Lahari / Soundarya Lahari boundary was
 * confirmed at verse 41/42 with manblunder.com's own commentary cited above.
 * Several verses (33, 37, 38, 44, 50) have a word/sandhi genuinely straddling
 * a pada boundary in wikisource's philologically fussier printing; the more
 * common self-contained-pada convention (matching every other source) was
 * used instead of preserving a mid-word line break. Verse 42's "नीडेयच्छाया"
 * compound and verse 31's tantra-critique are flagged as lower-confidence
 * renderings of genuinely dense compounds (the Sanskrit itself is firm).
 * Verse 49 is a wordplay verse where each epithet doubles as an ancient
 * city's name (Vishala, Kalyani, Ayodhya, Avanti, etc.) -- the translation
 * keeps the literal descriptive sense and notes the pun.
 *
 * Verses 51-75: cross-checked across six sources (vignanam.org,
 * amritanilayam.org, sa.wikisource.org, stotranidhi.com, shlokam.org,
 * vedadhara.com). Four real discrepancies resolved the same way: verse 67
 * चिबुकम् (chin) over wikisource's non-word "चुबुकम्", verse 72 परिमृशति
 * (touches) over a non-word "परिभृशति", verse 59 मुखमिदं (face) over a 4-1
 * minority "सुखमिदं", verse 61 वहन्नन्तर्मुक्ताः confirmed via shlokam.org's
 * word-gloss over a minority variant. Verse 51's "सौभाग्यजननी" vs.
 * "सौभाग्यजयिनी" is a legitimate attested alternate reading (not an error)
 * kept at the 5-source majority. Verse 70's "अन्धकरिपोः" is genuinely
 * ambiguous between commentaries on which deity is meant; rendered
 * generically and flagged.
 *
 * Verses 76-100: cross-checked against sa.wikisource.org and
 * amritanilayam.org, with search-based spot-checks against stotranidhi.com,
 * aanmeegam.org, ramyantar.com, and manblunder.com. Four real discrepancies
 * resolved toward the grammatical / multiply-attested reading: verse 81
 * लघुत्वं over a non-word "लधुत्वं", verse 82 भवती/विधिज्ञ्ये over
 * "भवति"/"विधिज्ञे" (भवती is needed as the subject of "असि"), verse 83
 * गर्भौ/यदग्रे over non-words "गभौ"/"यदग्ने", verse 86 तुलाकोटिक्वाणैः over
 * "तुलाकोटिक्काणैः". Verse 100 confirmed as a clean, natural closing verse
 * (comparing praise of the Goddess to waving lamps at the sun) with a
 * completion colophon immediately following in every source. Verse 86 is
 * flagged as a moderate-confidence rendering of a specific playful
 * husband-wife narrative that admits more than one reading.
 *
 * meaning_en is this script author's own translation composed from the
 * verified Sanskrit for every verse, matching the approach used for every
 * prior upload this session -- not copied from any single published
 * translator's wording.
 *
 * Devanagari is the source of truth (as verified above); Telugu and Tamil
 * are derived via Sanscript / the custom Tamil superscript converter, IAST
 * via Sanscript with this site's e->e-macron / o->o-macron convention.
 *
 * Pada structure: all 100 verses are 4 padas each (predominantly Shikharini
 * meter), danda after pada 2 only, nothing after padas 1/3, numbered
 * double-danda after pada 4 -- the standard shloka convention, confirmed
 * with no exceptions across all four research passes.
 *
 * Defaults to a dry run. Pass --write to apply.
 * Run: node scripts/upload-soundarya-lahari.mjs          (dry run)
 *      node scripts/upload-soundarya-lahari.mjs --write  (apply)
 */
import { google } from 'googleapis';
import * as dotenv from 'dotenv';
import { resolve, dirname } from 'path';
import { fileURLToPath } from 'url';
import Sanscript from '@indic-transliteration/sanscript';
import { devanagariToTamilSuperscript } from './lib-tamil-superscript.mjs';

const __dirname = dirname(fileURLToPath(import.meta.url));
dotenv.config({ path: resolve(__dirname, '../.env.local') });

const WRITE = process.argv.includes('--write');
const SLUG = 'soundarya-lahari';

const VERSES = [
  { padas: [`शिवः शक्त्या युक्तो यदि भवति शक्तः प्रभवितुं`, `न चेदेवं देवो न खलु कुशलः स्पन्दितुमपि`, `अतस्त्वामाराध्यां हरिहरविरिञ्चादिभिरपि`, `प्रणन्तुं स्तोतुं वा कथमकृतपुण्यः प्रभवति`], meaning: `Only when joined with Shakti is Shiva capable of creating the universe; without her he cannot even stir. So who, apart from someone rich in merit earned over past lives, could dare to bow to or praise you, O Devi, worshipped even by Hari, Hara, and Virinchi?` },
  { padas: [`तनीयांसं पांसुं तव चरणपङ्केरुहभवं`, `विरिञ्चिस्सञ्चिन्वन् विरचयति लोकानविकलम्`, `वहत्येनं शौरिः कथमपि सहस्रेण शिरसां`, `हरस्संक्षुद्यैनं भजति भसितोद्धूलनविधिम्`], meaning: `Gathering a mere speck of dust from your lotus feet, Virinchi fashions the flawless worlds; Shauri somehow bears that same dust on his thousand hoods; and Hara, grinding it into ash, smears it over his own body at the hour of dissolution.` },
  { padas: [`अविद्यानामन्तस्तिमिरमिहिरद्वीपनगरी`, `जडानां चैतन्यस्तबकमकरन्दस्रुतिझरी`, `दरिद्राणां चिन्तामणिगुणनिका जन्मजलधौ`, `निमग्नानां दंष्ट्रा मुररिपुवराहस्य भवति`], meaning: `To the ignorant you are the sunlit isle that burns away the darkness within; to the spiritually dull, a honeyed stream flowing from clustered blossoms of consciousness; to the poor sunk in the ocean of birth, a string of wish-granting gems; and to those drowning there, the tusk of the boar who slew the demon Mura.` },
  { padas: [`त्वदन्यः पाणिभ्यामभयवरदो दैवतगणः`, `त्वमेका नैवासि प्रकटितवराभीत्यभिनया`, `भयात् त्रातुं दातुं फलमपि च वाञ्छासमधिकं`, `शरण्ये लोकानां तव हि चरणावेव निपुणौ`], meaning: `Every other deity merely displays gestures of fearlessness and boon-granting with two hands, but you need no such display: your two feet alone are fully capable of shielding the fearful and giving even beyond what they wished for.` },
  { padas: [`हरिस्त्वामाराध्य प्रणतजनसौभाग्यजननीं`, `पुरा नारी भूत्वा पुररिपुमपि क्षोभमनयत्`, `स्मरोऽपि त्वां नत्वा रतिनयनलेह्येन वपुषा`, `मुनीनामप्यन्तः प्रभवति हि मोहाय महताम्`], meaning: `Hari, having worshipped you, once became a woman and thereby stirred even the slayer of the three cities; and Smara, having bowed to you, bears a form so delightful to the gaze of Rati that it can bewilder the minds of even great sages.` },
  { padas: [`धनुः पौष्पं मौर्वी मधुकरमयी पञ्च विशिखाः`, `वसन्तः सामन्तो मलयमरुदायोधनरथः`, `तथाप्येकः सर्वं हिमगिरिसुते कामपि कृपाम्`, `अपाङ्गात्ते लब्ध्वा जगदिदमनङ्गो विजयते`], meaning: `His bow is of flowers, his string a line of bees, his five arrows mere blossoms, spring his ally and the southern breeze his chariot for war - yet armed with nothing but a single glance of grace won from you, O daughter of the snow-mountain, the bodiless one conquers this entire world.` },
  { padas: [`क्वणत्काञ्चीदामा करिकलभकुम्भस्तननता`, `परिक्षीणा मध्ये परिणतशरच्चन्द्रवदना`, `धनुर्बाणान् पाशं सृणिमपि दधाना करतलैः`, `पुरस्तादास्तां नः पुरमथितुराहोपुरुषिका`], meaning: `Girdled with a tinkling chain of bells, her breasts full like the frontal domes of a young elephant, her waist slender, her face like the ripened autumn moon, holding bow, arrows, noose and goad in her hands - may that proud, self-assured presence of the consort of the destroyer of Pura stand ever before us.` },
  { padas: [`सुधासिन्धोर्मध्ये सुरविटपिवाटीपरिवृते`, `मणिद्वीपे नीपोपवनवति चिन्तामणिगृहे`, `शिवाकारे मञ्चे परमशिवपर्यङ्कनिलयां`, `भजन्ति त्वां धन्याः कतिचन चिदानन्दलहरीम्`], meaning: `In the middle of the ocean of nectar, ringed by a grove of celestial trees, on the jewelled island, within a house of wish-granting gems set amid a kadamba garden, upon a couch that is Shiva himself, reposing on the bed of Parama-Shiva - only a rare, fortunate few worship you there, the very surging wave of bliss-consciousness.` },
  { padas: [`महीं मूलाधारे कमपि मणिपूरे हुतवहं`, `स्थितं स्वाधिष्ठाने हृदि मरुतमाकाशमुपरि`, `मनोऽपि भ्रूमध्ये सकलमपि भित्वा कुलपथं`, `सहस्रारे पद्मे सह रहसि पत्या विहरसे`], meaning: `You abide as earth in the muladhara, as another element seated in the manipura, fixed in the svadhishthana, as breath in the heart, as space above that, and even as mind at the point between the brows - piercing through the hidden path, you sport in secret with your lord in the thousand-petalled lotus above. (The precise element-to-chakra assignments here are debated among traditional commentators; rendered literally rather than favoring one gloss.)` },
  { padas: [`सुधाधारासारैश्चरणयुगलान्तर्विगलितैः`, `प्रपञ्चं सिञ्चन्ती पुनरपि रसाम्नायमहसः`, `अवाप्य स्वां भूमिं भुजगनिभमध्युष्टवलयं`, `स्वमात्मानं कृत्वा स्वपिषि कुलकुण्डे कुहरिणि`], meaning: `Streams of nectar drip down between your two feet, again and again drenching the manifest world with the radiance of the esoteric transmission; and having reclaimed your own ground, coiled two and a half times like a serpent, you lie there, making your very self the resting place, deep within the secret Kula cavity.` },
  { padas: [`चतुर्भिः श्रीकण्ठैः शिवयुवतिभिः पञ्चभिरपि`, `प्रभिन्नाभिः शम्भोर्नवभिरपि मूलप्रकृतिभिः`, `चतुश्चत्वारिंशद्वसुदलकलाश्रत्रिवलय`, `त्रिरेखाभिः सार्धं तव शरणकोणाः परिणताः`], meaning: `With four Shrikanthas, and also with five Shiva-consorts split further into nine root-natures, together with forty-four petalled digits arranged in triple enclosures and triple lines - thus, O Devi, the corners of your refuge, the Sri Chakra, have taken their form.` },
  { padas: [`त्वदीयं सौन्दर्यं तुहिनगिरिकन्ये तुलयितुं`, `कवीन्द्राः कल्पन्ते कथमपि विरिञ्चिप्रभृतयः`, `यदालोकौत्सुक्यादमरललना यान्ति मनसा`, `तपोभिर्दुष्प्रापामपि गिरिशसायुज्यपदवीम्`], meaning: `To measure your beauty, O daughter of the snow-mountain, even the greatest poets, Virinchi foremost among them, can only attempt in vain; and merely to catch a glimpse of it, the celestial women long so intensely that, through longing alone, their minds reach the very state of union with Girisha that ascetics struggle for through austerity.` },
  { padas: [`नरं वर्षीयांसं नयनविरसं नर्मसु जडं`, `तवापाङ्गालोके पतितमनुधावन्ति शतशः`, `गलद्वेणीबन्धाः कुचकलशविस्रस्तसिचया`, `हठात् त्रुट्यत्काञ्च्यो विगलितदुकूला युवतयः`], meaning: `Even an old man, dull-eyed and inept at love-play, is chased by hundreds of young women the moment he falls under a single side-glance of your grace - women whose braided hair comes loose, whose garments slip from the pitchers of their breasts, and whose girdle-strings snap of their own accord.` },
  { padas: [`क्षितौ षट्पञ्चाशद् द्विसमधिकपञ्चाशदुदके`, `हुताशे द्वाषष्टिश्चतुरधिकपञ्चाशदनिले`, `दिवि द्विष्षट्त्रिंशन्मनसि च चतुष्षष्टिरिति ये`, `मयूखास्तेषामप्युपरि तव पादाम्बुजयुगम्`], meaning: `Fifty-six rays belong to earth, fifty-two to water, sixty-two to fire, fifty-four to air, thirty-two to sky, and sixty-four to mind - yet above even all of these rays stands the pair of your lotus feet. (The deeper tattva scheme behind these ray-counts is likewise debated among commentators; the Sanskrit and the numbers themselves are firm, only the esoteric gloss is contested.)` },
  { padas: [`शरज्ज्योत्स्नाशुद्धां शशियुतजटाजूटमकुटां`, `वरत्रासत्राणस्फटिकघटिकापुस्तककराम्`, `सकृन्न त्वा नत्वा कथमिव सतां संन्निदधते`, `मधुक्षीरद्राक्षामधुरिमधुरीणाः फणितयः`], meaning: `Pure as the moonlight of autumn, crowned with matted locks bearing a digit of the moon, holding in your hands a protecting cord, a crystal rosary and a book - without bowing to you even once, how could the wise ever produce speech sweeter than milk, nectar, and grapes?` },
  { padas: [`कवीन्द्राणां चेतःकमलवनबालातपरुचिं`, `भजन्ते ये सन्तः कतिचिदरुणामेव भवतीम्`, `विरिञ्चिप्रेयस्यास्तरुणतरशृङ्गारलहरी`, `गभीराभिर्वाग्भिर्विदधति सतां रञ्जनममी`], meaning: `Some rare, blessed souls who cherish even a faint reddish trace of you - like the first light of dawn falling on the lotus-grove of a poet's heart - go on, through deep words that are youthful waves of the romantic mood belonging to Virinchi's beloved, to delight the good and the wise.` },
  { padas: [`सवित्रीभिर्वाचां शशिमणिशिलाभङ्गरुचिभिः`, `वशिन्याद्याभिस्त्वां सह जननि संचिन्तयति यः`, `स कर्ता काव्यानां भवति महतां भङ्गिरुचिभिः`, `वचोभिर्वाग्देवीवदनकमलामोदमधुरैः`], meaning: `Whoever meditates on you, O Mother, together with Vashini and the other goddesses of speech, radiant as fragments of moon-gem, becomes himself the composer of great works, through words fragrant and graceful as the lotus-mouth of the goddess of speech.` },
  { padas: [`तनुच्छायाभिस्ते तरुणतरणिश्रीसरणिभिः`, `दिवं सर्वामुर्वीमरुणिमनि मग्नां स्मरति यः`, `भवन्त्यस्य त्रस्यद्वनहरिणशालीननयनाः`, `सहोर्वश्या वश्याः कति कति न गीर्वाणगणिकाः`], meaning: `Whoever recalls the whole earth and sky steeped in your reddish glow, itself no different from the beauty of the rising young sun - for him, women with the shy, startled glance of forest deer grow submissive, Urvashi among them; indeed, is there any celestial courtesan at all who would not fall under his sway?` },
  { padas: [`मुखं बिन्दुं कृत्वा कुचयुगमधस्तस्य तदधो`, `हरार्धं ध्यायेद्यो हरमहिषि ते मन्मथकलाम्`, `स सद्यः संक्षोभं नयति वनिता इत्यतिलघु`, `त्रिलोकीमप्याशु भ्रमयति रवीन्दुस्तनयुगाम्`], meaning: `Whoever meditates upon your face as the bindu, the pair of breasts just below it, and beneath that the half-form of Hara, absorbed in your art of passion as the consort of Hara - he effortlessly stirs any woman to longing, and just as swiftly sets the sun-and-moon-breasted triple world trembling.` },
  { padas: [`किरन्तीमङ्गेभ्यः किरणनिकुरम्बामृतरसं`, `हृदि त्वामाधत्ते हिमकरशिलामूर्तिमिव यः`, `स सर्पाणां दर्पं शमयति शकुन्ताधिप इव`, `ज्वरप्लुष्टान् दृष्ट्या सुखयति सुधाधारसिरया`], meaning: `Whoever holds in the heart an image of you, moon-white, pouring streams of nectar-rays from every limb, subdues the pride of serpents as easily as the king of birds, and with a mere glance soothes those burning with fever, as if bathing them in a river of nectar.` },
  { padas: [`तटिल्लेखातन्वीं तपनशशिवैश्वानरमयीं`, `निषण्णां षण्णामप्युपरि कमलानां तव कलाम्`, `महापद्माटव्यां मृदितमलमायेन मनसा`, `महान्तः पश्यन्तो दधति परमाह्लादलहरीम्`], meaning: `Meditating on your subtle digit, slender as a streak of lightning, woven of sun, moon and fire, seated above even the six lotuses in the great lotus-forest of the crown, with a mind scoured clean of the taint of illusion - the great ones who behold this bear within themselves the very wave of supreme bliss.` },
  { padas: [`भवानि त्वं दासे मयि वितर दृष्टिं सकरुणा`, `मिति स्तोतुं वाञ्छन् कथयति भवानि त्वमिति यः`, `तदैव त्वं तस्मै दिशसि निजसायुज्यपदवीं`, `मुकुन्दब्रह्मेन्द्रस्फुटमकुटनीराजितपदाम्`], meaning: `Whoever, wishing only to praise you, gets no further than saying, O Bhavani, cast your compassionate glance on me, your servant - to him you grant, that very instant, your own state of union, whose feet are lit by the waving lamps held in the crowns of Mukunda, Brahma, and Indra.` },
  { padas: [`त्वया हृत्वा वामं वपुरपरितृप्तेन मनसा`, `शरीरार्धं शम्भोरपरमपि शङ्के हृतमभूत्`, `यदेतत्त्वद्रूपं सकलमरुणाभं त्रिनयनं`, `कुचाभ्यामानम्रं कुटिलशशिचूडालमकुटम्`], meaning: `Having stolen, with a mind still unsatisfied, the left half of Shiva's body, I suspect you have by now taken the remaining half as well - for this whole reddish, three-eyed form now bears, above breasts pressed close together, the very crescent-crested crown of Shiva.` },
  { padas: [`जगत्सूते धाता हरिरवति रुद्रः क्षपयते`, `तिरस्कुर्वन्नेतत्स्वमपि वपुरीशस्तिरयति`, `सदापूर्वः सर्वं तदिदमनुगृह्णाति च शिव`, `स्तवाज्ञामालम्ब्य क्षणचलितयोर्भ्रूलतिकयोः`], meaning: `Brahma brings forth the world, Hari sustains it, Rudra dissolves it, Ishvara conceals even his own form, and the ever-prior Sadashiva graciously restores it all again - each of them acting only by leave of your command, given through the barest tremor of your two eyebrow-creepers.` },
  { padas: [`त्रयाणां देवानां त्रिगुणजनितानां तव शिवे`, `भवेत् पूजा पूजा तव चरणयोर्या विरचिता`, `तथा हि त्वत्पादोद्वहनमणिपीठस्य निकटे`, `स्थिता ह्येते शश्वन्मुकुलितकरोत्तंसमकुटाः`], meaning: `Whatever worship is offered at your two feet becomes, by that very act, worship of the three gods born of your three gunas - for close beside the jewelled pedestal that bears the print of your feet, these three stand forever with folded hands and bowed, garlanded crowns.` },
  { padas: [`विरिञ्चिः पञ्चत्वं व्रजति हरिराप्नोति विरतिं`, `विनाशं कीनाशो भजति धनदो याति निधनम्`, `वितन्द्री माहेन्द्री विततिरपि संमीलितदृशा`, `महासंहारेऽस्मिन्विहरति सति त्वत्पतिरसौ`], meaning: `At the great cosmic dissolution Brahma perishes, Vishnu's activity ceases, Yama himself dies, Kubera the lord of wealth meets his end, and even the tireless host of Indra's gods sits with eyes closed - yet in that very dissolution your husband Shiva alone continues to sport, untouched, thanks to your presence beside him.` },
  { padas: [`जपो जल्पः शिल्पं सकलमपि मुद्राविरचना`, `गतिः प्रादक्षिण्यक्रमणमशनाद्याहुतिविधिः`, `प्रणामः संवेशः सुखमखिलमात्मार्पणदृशा`, `सपर्यापर्यायस्तव भवतु यन्मे विलसितम्`], meaning: `May everything I do - my speech becoming recitation, my idle talk becoming ritual skill, my gestures becoming sacred hand-seals, my walking becoming circling around you, my eating becoming an offered oblation, my prostration, my rest, my pleasure - become, through the vision of surrendering myself to you, one unbroken sequence of worship offered to you.` },
  { padas: [`सुधामप्यास्वाद्य प्रतिभयजरामृत्युहरिणीं`, `विपद्यन्ते विश्वे विधिशतमखाद्या दिविषदः`, `करालं यत्क्ष्वेलं कबलितवतः कालकलना`, `न शंभोस्तन्मूलं तव जननि ताटङ्कमहिमा`], meaning: `Even after tasting the nectar that removes the terror of old age and death, Brahma, Indra and all the other gods still eventually perish; but Shiva, who once swallowed the terrifying poison, knows no such end - O Mother, that is the true greatness of your ear-ornament, which alone grants him real immortality.` },
  { padas: [`किरीटं वैरिञ्चं परिहर पुरः कैटभभिदः`, `कठोरे कोटीरे स्खलसि जहि जम्भारिमकुटम्`, `प्रणम्रेष्वेतेषु प्रसभमुपयातस्य भवनं`, `भवस्याभ्युत्थाने तव परिजनोक्तिर्विजयते`], meaning: `Step around Brahma's crown, don't stumble on Vishnu's hard diadem, push past Indra's crown - such is the triumphant cry of your attendants as Shiva forces his way into his own house past these gods who bow and rise up before you both.` },
  { padas: [`स्वदेहोद्भूताभिर्घृणिभिरणिमाद्याभिरभितः`, `निषेव्ये नित्ये त्वामहमिति सदा भावयति यः`, `किमाश्चर्यं तस्य त्रिनयनसमृद्धिं तृणयतः`, `महासंवर्ताग्निर्विरचयति नीराजनविधिम्`], meaning: `What wonder is it that for the one who constantly meditates "I am You," O eternal one served on every side by powers like anima born from your own body, even the great fire of universal dissolution performs a lamp-waving rite of homage before him, while he regards even three-eyed Shiva's own splendor as mere straw?` },
  { padas: [`चतुःषष्ट्या तन्त्रैः सकलमतिसन्धाय भुवनं`, `स्थितस्तत्तत्सिद्धिप्रसवपरतन्त्रैः पशुपतिः`, `पुनस्त्वन्निर्बन्धादखिलपुरुषार्थैकघटना`, `स्वतन्त्रं ते तन्त्रं क्षितितलमवातीतरदिदम्`], meaning: `Having first misled the whole world with sixty-four tantras, each dependent on yielding only its own limited power, Shiva let them stand - but then, at your insistence alone, your own independent teaching, complete in itself and able to grant all four aims of human life together, descended and crossed over onto this earth. (Lower confidence: this critique-of-other-tantras reading is the standard one, but the compound is dense.)` },
  { padas: [`शिवः शक्तिः कामः क्षितिरथ रविः शीतकिरणः`, `स्मरो हंसः शक्रस्तदनु च परामारहरयः`, `अमी हृल्लेखाभिस्तिसृभिरवसानेषु घटिताः`, `भजन्ते वर्णास्ते तव जननि नामावयवताम्`], meaning: `Shiva, Shakti, Kama, Earth, then Sun, Moon, Smara, Hamsa, Shakra, and after them Para, Mara and Hari - these seed-syllables, each joined at its end to the three hrllekha syllables, become, O Mother, the very letters that compose your mantric name.` },
  { padas: [`स्मरं योनिं लक्ष्मीं त्रितयमिदमादौ तव मनोः`, `निधायैके नित्ये निरवधिमहाभोगरसिकाः`, `भजन्ति त्वां चिन्तामणिगुणनिबद्धाक्षवलयाः`, `शिवाग्नौ जुह्वन्तः सुरभिघृतधाराहुतिशतैः`], meaning: `Placing these three seed-syllables - Smara, Yoni and Lakshmi - at the very start of your mantra, some devotees, O eternal one, relishing boundless enjoyment, worship you with rosaries strung from wish-fulfilling gem beads, offering hundreds of oblations of fragrant ghee-streams into the fire that is Shiva.` },
  { padas: [`शरीरं त्वं शंभोः शशिमिहिरवक्षोरुहयुगं`, `तवात्मानं मन्ये भगवति नवात्मानमनघम्`, `अतः शेषः शेषीत्ययमुभयसाधारणतया`, `स्थितः संबन्धो वां समरसपरानन्दपरयोः`], meaning: `You are the body of Shambhu, and I take his two breasts to be the moon and sun; O sinless one, I take your very self likewise to be his ninefold self - so this relation of the supported and the supporter holds equally between you both, united as you are in one undivided supreme bliss.` },
  { padas: [`मनस्त्वं व्योम त्वं मरुदसि मरुत्सारथिरसि`, `त्वमापस्त्वं भूमिस्त्वयि परिणतायां न हि परम्`, `त्वमेव स्वात्मानं परिणमयितुं विश्ववपुषा`, `चिदानन्दाकारं शिवयुवति भावेन बिभृषे`], meaning: `You are mind, you are space, you are wind, you are fire, you are water, you are earth - once you have transformed into these, nothing remains beyond you; O youthful consort of Shiva, it is you alone who, in order to manifest your own self as the body of the whole universe, bear yourself in the form of pure consciousness-bliss.` },
  { padas: [`तवाज्ञाचक्रस्थं तपनशशिकोटिद्युतिधरं`, `परं शंभुं वन्दे परिमिलितपार्श्वं परचिता`, `यमाराध्यन्भक्त्या रविशशिशुचीनामविषये`, `निरालोकेऽलोके निवसति हि भालोकभुवने`], meaning: `I bow to the supreme Shambhu seated in your Ajna-chakra, bearing the splendor of a million suns and moons, seated side by side with your supreme awareness - whoever devoutly worships him comes to dwell in that forehead-realm of light beyond the reach of sun, moon or fire, unlit by any of them.` },
  { padas: [`विशुद्धौ ते शुद्धस्फटिकविशदं व्योमजनकं`, `शिवं सेवे देवीमपि शिवसमानव्यवसिताम्`, `ययोः कान्त्या यान्त्याः शशिकिरणसारूप्यसरणेः`, `विधूतान्तर्ध्वान्ता विलसति चकोरीव जगती`], meaning: `In your Vishuddhi-chakra I worship Shiva, clear as pure crystal and the source of space, together with the Goddess who shares his very resolve - by whose combined radiance, resembling moonbeams, the world, its inner darkness dispelled, shines like a chakori bird that lives on moonlight.` },
  { padas: [`समुन्मीलत्संवित्कमलमकरन्दैकरसिकं`, `भजे हंसद्वन्द्वं किमपि महतां मानसचरम्`, `यदालापादष्टादशगुणितविद्यापरिणतिः`, `यदादत्ते दोषाद्गुणमखिलमद्भ्यः पय इव`], meaning: `I worship that indescribable pair of swans roaming the Manasa-lake of great souls, delighting only in the nectar of the freshly-opening lotus of pure awareness - from whose murmuring speech comes the full ripening of the eighteen branches of knowledge, and who draw out only the good from everything, faultless, just as milk alone is drawn from water.` },
  { padas: [`तव स्वाधिष्ठाने हुतवहमधिष्ठाय निरतं`, `तमीडे संवर्तं जननि महतीं तां च समयाम्`, `यदालोके लोकान्दहति महति क्रोधकालिते`, `दयार्द्रा या दृष्टिः शिशिरमुपचारं रचयति`], meaning: `O Mother, I praise the great fire Samvarta seated constantly in your Svadhishthana-chakra, together with the great goddess Samaya who presides there - that same fire whose gaze, when darkened with wrath, burns up the worlds, yet whose gaze, when melted with compassion, becomes instead a cooling remedy.` },
  { padas: [`तटित्वन्तं शक्त्या तिमिरपरिपन्थिस्फुरणया`, `स्फुरन्नानारत्नाभरणपरिणद्धेन्द्रधनुषम्`, `तव श्यामं मेघं कमपि मणिपूरैकशरणं`, `निषेवे वर्षन्तं हरमिहिरतप्तं त्रिभुवनम्`], meaning: `I worship that indescribable dark cloud of yours dwelling in your Manipura-chakra, flashing with the lightning-power that dispels darkness, girded with a rainbow of gleaming, many-colored jewel-ornaments, raining relief upon the three worlds scorched by the fires of dissolution and by the sun.` },
  { padas: [`तवाधारे मूले सह समयया लास्यपरया`, `नवात्मानं मन्ये नवरसमहाताण्डवनटम्`, `उभाभ्यामेताभ्यामुदयविधिमुद्दिश्य दयया`, `सनाथाभ्यां जज्ञे जनकजननीमज्जगदिदम्`], meaning: `In your Muladhara-chakra, together with Samaya who is devoted to dance, I contemplate Shiva as the nine-fold self performing the great dance of the nine sentiments - and by this pair, moved by compassion and intent on bringing the universe into being, each accompanied by the other as its true lord, this whole world was born, with them as its father and mother.` },
  { padas: [`गतैर्माणिक्यत्वं गगनमणिभिः सान्द्रघटितं`, `किरीटं ते हैमं हिमगिरिसुते कीर्तयति यः`, `स नीडेयच्छायाच्छुरणशबलं चन्द्रशकलं`, `धनुः शौनासीरं किमिति न निबध्नाति धिषणाम्`], meaning: `O daughter of the Himalaya, whoever praises your golden crown, densely set with sky-jewels turned ruby-red by their nearness to the gold - why should his mind not also conclude that the crescent moon set beside it, dappled with that same iridescent shimmer, must itself be a fragment of Indra's rainbow bow? (Lower confidence: the "नीडेयच्छाया" image is one of the most obscure compounds in the whole hymn; this follows the common reading of the crown's brilliance being mistaken for a rainbow.)` },
  { padas: [`धुनोतु ध्वान्तं नस्तुलितदलितेन्दीवरवनं`, `घनस्निग्धश्लक्ष्णं चिकुरनिकुरुम्बं तव शिवे`, `यदीयं सौरभ्यं सहजमुपलब्धुं सुमनसो`, `वसन्त्यस्मिन्मन्ये वलमथनवाटीविटपिनाम्`], meaning: `O Auspicious One, may your mass of hair - thick, glossy and soft, like a whole forest of freshly-opened blue lotuses - dispel our darkness; I think the flowering trees of Indra's own garden have come to dwell within it, just to obtain its natural fragrance for themselves.` },
  { padas: [`तनोतु क्षेमं नस्तव वदनसौन्दर्यलहरी`, `परीवाहः स्रोतःसरणिरिव सीमन्तसरणिः`, `वहन्ती सिन्दूरं प्रबलकबरीभारतिमिर`, `द्विषां बृन्दैर्बन्दीकृतमिव नवीनार्ककिरणम्`], meaning: `May the path of your hair-parting grant us wellbeing - it is like the very channel through which the flood of your face's beauty overflows, carrying vermillion as though it were a freshly-risen sunbeam taken captive by the dark host of your thick, heavy tresses.` },
  { padas: [`अरालैः स्वाभाव्यादलिकलभसश्रीभिरलकैः`, `परीतं ते वक्त्रं परिहसति पङ्केरुहरुचिम्`, `दरस्मेरे यस्मिन्दशनरुचिकिञ्जल्करुचिरे`, `सुगन्धौ माद्यन्ति स्मरदहनचक्षुर्मधुलिहः`], meaning: `Your face, framed by naturally curling locks lovely as young bees, mocks even the beauty of the lotus; and on that gently-smiling, fragrant face, lovely with the pollen-like gleam of your teeth, even the bees that serve as the eyes of Shiva, burner of Kama, grow intoxicated.` },
  { padas: [`ललाटं लावण्यद्युतिविमलमाभाति तव यत्`, `द्वितीयं तन्मन्ये मकुटघटितं चन्द्रशकलम्`, `विपर्यासन्यासादुभयमपि संभूय च मिथः`, `सुधालेपस्यूतिः परिणमति राकाहिमकरः`], meaning: `Your forehead, radiant and flawless with the glow of beauty, I take to be a second crescent moon fixed into your crown; and when the two are turned around and joined together, the seams of nectar-plaster where they meet melt into each other, and together they become the single, full moon.` },
  { padas: [`भ्रुवौ भुग्ने किंचिद्भुवनभयभङ्गव्यसनिनि`, `त्वदीये नेत्राभ्यां मधुकररुचिभ्यां धृतगुणम्`, `धनुर्मन्ये सव्येतरकरगृहीतं रतिपतेः`, `प्रकोष्ठे मुष्टौ च स्थगयति निगूढान्तरमुमे`], meaning: `O Uma, ever devoted to dispelling the world's fear, I take your two slightly-curved eyebrows to be a single bow of Kama, strung with your two bee-dark eyes as its cord, held in his left hand - with the wrist and fist at the outer ends concealing what lies hidden in the bow's middle.` },
  { padas: [`अहः सूते सव्यं तव नयनमर्कात्मकतया`, `त्रियामां वामं ते सृजति रजनीनायकतया`, `तृतीया ते दृष्टिर्दरदलितहेमाम्बुजरुचिः`, `समाधत्ते सन्ध्यां दिवसनिशयोरन्तरचरीम्`], meaning: `Your right eye, being of the nature of the sun, gives birth to the day; your left eye, being of the nature of the moon, creates the night; and your third eye, lovely as a half-opened golden lotus, produces the twilight that moves between day and night.` },
  { padas: [`विशाला कल्याणी स्फुटरुचिरयोध्या कुवलयैः`, `कृपाधाराधारा किमपि मधुराभोगवतिका`, `अवन्ती दृष्टिस्ते बहुनगरविस्तारविजया`, `ध्रुवं तत्तन्नामव्यवहरणयोग्या विजयते`], meaning: `Your glance triumphs, having conquered the range of many a city whose very names it deserves to bear: it is vast (Vishala), auspicious (Kalyani), of manifest beauty like the unconquerable Ayodhya, lovely as a blue lotus (Kuvalaya), a fount of compassion, some indescribably sweet realm of enjoyment, and, like Avanti, it truly presides over all it surveys. (Each epithet here is a deliberate double meaning with the name of a real ancient city.)` },
  { padas: [`कवीनां संदर्भस्तबकमकरन्दैकरसिकं`, `कटाक्षव्याक्षेपभ्रमरकलभौ कर्णयुगलम्`, `अमुञ्चन्तौ दृष्ट्वा तव नवरसास्वादतरलौ`, `असूयासंसर्गादलिकनयनं किंचिदरुणम्`], meaning: `Your two sidelong glances are like a pair of young bees that, tasting only the nectar of the clustered blossoms of poets' compositions, dart toward your two ears without ever leaving them - and seeing this pair trembling as they taste the nine poetic sentiments, your forehead-eye reddens slightly out of envy at being left out.` },
  { padas: [`शिवे शृङ्गारार्द्रा तदितरजने कुत्सनपरा`, `सरोषा गङ्गायां गिरिशचरिते विस्मयवती`, `हराहिभ्यो भीता सरसिरुहसौभाग्यजननी`, `सखीषु स्मेरा ते मयि जननी दृष्टिः सकरुणा`], meaning: `Toward Shiva your gaze is tender with love, toward others scornful, jealous-angry at the Ganga, astonished when Shiva's deeds are told, fearful of his serpent-ornaments, playfully smiling among your friends, and compassionate when it falls on me - and through it all, mother, it is that very glance which is the source of the lotus's own loveliness.` },
  { padas: [`गते कर्णाभ्यर्णं गरुत इव पक्ष्माणि दधती`, `पुरां भेत्तुश्चित्तप्रशमरसविद्रावणफले`, `इमे नेत्रे गोत्राधरपतिकुलोत्तंसकलिके`, `तवाकर्णाकृष्टस्मरशरविलासं कलयतः`], meaning: `Your two eyes, their lashes curving back toward the ears like feathers, are the crowning buds of the eyebrow-lineage; capable at once of shattering and soothing the composure of the Destroyer of the Three Cities, they carry out the sport of Kama's arrow drawn back to the ear.` },
  { padas: [`विभक्तत्रैवर्ण्यं व्यतिकरितलीलाञ्जनतया`, `विभाति त्वन्नेत्रत्रितयमिदमीशानदयिते`, `पुनः स्रष्टुं देवान् द्रुहिणहरिरुद्रानुपरतान्`, `रजः सत्त्वं बिभ्रत्तम इति गुणानां त्रयमिव`], meaning: `Your triad of eyes shines with three distinct colors, as if playfully smeared with three shades of collyrium, O beloved of Ishana; bearing rajas, sattva, and tamas between them, they seem poised to recreate Brahma, Vishnu, and Rudra should those gods ever lapse into quiescence.` },
  { padas: [`पवित्रीकर्तुं नः पशुपतिपराधीनहृदये`, `दयामित्रैर्नेत्रैररुणधवलश्यामरुचिभिः`, `नदः शोणो गङ्गा तपनतनयेति ध्रुवममुं`, `त्रयाणां तीर्थानामुपनयसि सम्भेदमनघम्`], meaning: `To purify us, whose hearts are surrendered to Pashupati, you bring near, through your compassionate eyes tinted red, white, and dark, what feels like the sinless confluence of three sacred rivers: the red Shona, the white Ganga, and the dark daughter of the sun.` },
  { padas: [`निमेषोन्मेषाभ्यां प्रलयमुदयं याति जगती`, `तवेत्याहुः सन्तो धरणिधरराजन्यतनये`, `त्वदुन्मेषाज्जातं जगदिदमशेषं प्रलयतः`, `परित्रातुं शङ्के परिहृतनिमेषास्तव दृशः`], meaning: `The wise say, O daughter of the mountain-king, that the whole world dissolves and rises again by the mere closing and opening of your eyes; I suspect, then, that you keep them ever unblinking, simply to guard this entire world - born of your opening them - from being swallowed by the very dissolution a blink would bring.` },
  { padas: [`तवापर्णे कर्णेजपनयनपैशुन्यचकिता`, `निलीयन्ते तोये नियतमनिमेषाः शफरिकाः`, `इयं च श्रीर्बद्धच्छदपुटकवाटं कुवलयम्`, `जहाति प्रत्यूषे निशि च विघटय्य प्रविशति`], meaning: `Startled by the tale-telling glances that whisper into your ear, O Parvati, even the restless little fish always hide motionless in the water; and Lakshmi's own blue lotus, its petals shut like a bolted door, opens only at dawn and, unlatching itself again, withdraws into hiding each night.` },
  { padas: [`दृशा द्राघीयस्या दरदलितनीलोत्पलरुचा`, `दवीयांसं दीनं स्नपय कृपया मामपि शिवे`, `अनेनायं धन्यो भवति न च ते हानिरियता`, `वने वा हर्म्ये वा समकरनिपातो हिमकरः`], meaning: `With that long glance of yours, colored like a half-opened blue lotus, bathe even wretched, distant me in your mercy, O consort of Shiva - this makes one blessed, and costs you nothing, just as moonlight falls equally on a forest hut and on a palace.` },
  { padas: [`अरालं ते पालीयुगलमगराजन्यतनये`, `न केषामाधत्ते कुसुमशरकोदण्डकुतुकम्`, `तिरश्चीनो यत्र श्रवणपथमुल्लङ्घ्य विलसन्`, `नपाङ्गव्यासङ्गो दिशति शरसन्धानधिषणाम्`], meaning: `Your curved pair of eyebrows, O daughter of the mountain-king, stirs in everyone a fascination with Kama's flower-bow; where it slants past even the reach of your ear, the play of your sidelong glance there takes on the very intent of an arrow being fitted to the string.` },
  { padas: [`स्फुरद्गण्डाभोगप्रतिफलितताटङ्कयुगलं`, `चतुश्चक्रं मन्ये तव मुखमिदं मन्मथरथम्`, `यमारुह्य द्रुह्यत्यवनिरथमर्केन्दुचरणं`, `महावीरो मारः प्रमथपतये सज्जितवते`], meaning: `I take this face of yours - its pair of quivering earrings mirrored on the swell of your cheeks - to be the four-wheeled chariot of Manmatha, the very one that the great warrior Kama mounts to make war on the lord of Shiva's hosts.` },
  { padas: [`सरस्वत्याः सूक्तीरमृतलहरीकौशलहरीः`, `पिबन्त्याः शर्वाणि श्रवणचुलुकाभ्यामविरलम्`, `चमत्कारश्लाघाचलितशिरसः कुण्डलगणो`, `झणत्कारैस्तारैः प्रतिवचनमाचष्ट इव ते`], meaning: `As your ears drink in, without pause and as if cupped in your two palms, Saraswati's wave-of-nectar-skilled sayings, your cluster of earrings, shaking as your head nods in wonder at each fine phrase, seems to ring out a jingling answer of its own applause.` },
  { padas: [`असौ नासावंशस्तुहिनगिरिवंशध्वजपटि`, `त्वदीयो नेदीयः फलतु फलमस्माकमुचितम्`, `वहन्नन्तर्मुक्ताः शिशिरतरनिश्वासगलितं`, `समृद्ध्या यत्तासां बहिरपि च मुक्तामणिधरः`], meaning: `May this ridge of your nose - a fine stalk proclaiming, banner-like, the bamboo lineage of the snow-mountain - grant us, close as it is to you, the fruit we deserve; bearing within it pearl-like drops distilled from your very cool breath, it wears, true to that hidden abundance, a string of pearls outside as well.` },
  { padas: [`प्रकृत्या रक्तायास्तव सुदति दन्तच्छदरुचेः`, `प्रवक्ष्ये सादृश्यं जनयतु फलं विद्रुमलता`, `न बिम्बं तद्बिम्बप्रतिफलनरागादरुणितं`, `तुलामध्यारोढुं कथमिव विलज्जेत कलया`], meaning: `Your lower lip, fair-toothed one, is red by its own nature; if I try to liken it to the coral creeper, let that comparison bear whatever fruit it can - for it is not even the bimba fruit that reddens by reflecting your lip, but the reverse, so how could coral ever dare step onto the scale to be weighed against you?` },
  { padas: [`स्मितज्योत्स्नाजालं तव वदनचन्द्रस्य पिबतां`, `चकोराणामासीदतिरसतया चञ्चुजडिमा`, `अतस्ते शीतांशोरमृतलहरीमम्लरुचयः`, `पिबन्ति स्वच्छन्दं निशि निशि भृशं काञ्जिकधिया`], meaning: `As the chakora birds drink in the moonlight-net of your smiling, moon-like face, their beaks turn numb from a taste too rich for them; and so, no longer able to stomach it, they now drink the real moon's nectar-waves each night as though it were merely sour gruel, out of sheer distaste by comparison.` },
  { padas: [`अविश्रान्तं पत्युर्गुणगणकथाम्रेडनजपा`, `जपापुष्पच्छाया तव जननि जिह्वा जयति सा`, `यदग्रासीनायाः स्फटिकदृषदच्छच्छविमयी`, `सरस्वत्या मूर्तिः परिणमति माणिक्यवपुषा`], meaning: `Your tongue, mother, forever murmuring in soft repetition the praises of your husband's virtues, glows red like the japa-flower and triumphs even over Saraswati - indeed, seated at its tip, her own crystal-clear form seems transformed here into a body of ruby.` },
  { padas: [`रणे जित्वा दैत्यानपहृतशिरस्त्रैः कवचिभिर्`, `निवृत्तैश्चण्डांशत्रिपुरहरनिर्माल्यविमुखैः`, `विशाखेन्द्रोपेन्द्रैः शशिविशदकर्पूरशकला`, `विलीयन्ते मातस्तव वदनताम्बूलकबलाः`], meaning: `Skanda, Indra, and Vishnu - armored, their helmets still on, returning triumphant from battle with the demons, yet too humble even to touch Shiva's own discarded worship-garlands - instead let dissolve on their tongues, mother, these camphor-white morsels of betel left over from your mouth.` },
  { padas: [`विपञ्च्या गायन्ती विविधमपदानं पशुपतेः`, `त्वयारब्धे वक्तुं चलितशिरसा साधुवचने`, `तदीयैर्माधुर्यैरपलपिततन्त्रीकलरवां`, `निजां वीणां वाणी निचुलयति चोलेन निभृतम्`], meaning: `The instant you nod your head and begin, lute in hand, to sing the manifold exploits of Shiva in fine words, Saraswati - her own vina's soft string-music silenced and outshone by the sweetness of yours - quietly slips her instrument into a cloth cover, out of embarrassment.` },
  { padas: [`कराग्रेण स्पृष्टं तुहिनगिरिणा वत्सलतया`, `गिरीशेनोदस्तं मुहुरधरपानाकुलतया`, `करग्राह्यं शम्भोर्मुखमुकुरवृन्तं गिरिसुते`, `कथङ्कारं ब्रूमस्तव चिबुकमौपम्यरहितम्`], meaning: `Touched by the Himalaya's own fingertips out of fatherly affection, again and again lifted by Shiva himself, restless to drink from your lips - this handle, as it were, of the mirror that is your face: how, O mountain's daughter, could we possibly describe your chin, when nothing else compares to it?` },
  { padas: [`भुजाश्लेषान् नित्यं पुरदमयितुः कण्टकवती`, `तव ग्रीवा धत्ते मुखकमलनालश्रियमियम्`, `स्वतः श्वेता कालागुरुबहुलजम्बालमलिना`, `मृणालीलालित्यं वहति यदधो हारलतिका`], meaning: `Forever raised in gooseflesh from the embraces of the destroyer of the three cities, your neck carries the charm of a lotus-stalk holding up the lotus of your face; and just below it, your pearl-string, naturally white but faintly darkened by dark aguru-unguent, only deepens that same lotus-stalk beauty.` },
  { padas: [`गले रेखास्तिस्रो गतिगमकगीतैकनिपुणे`, `विवाहव्यानद्धप्रगुणगुणसङ्ख्याप्रतिभुवः`, `विराजन्ते नानाविधमधुररागाकरभुवां`, `त्रयाणां ग्रामाणां स्थितिनियमसीमान इव ते`], meaning: `The three fine lines that crease your throat, O mistress of every subtlety of melody and ornament, shine out like the fixed boundary-marks of the three ancient musical scales, standing surety, as it were, for the tuned notes proper to a wedding song, from which every sweet raga is born.` },
  { padas: [`मृणालीमृद्वीनां तव भुजलतानां चतसृणां`, `चतुर्भिः सौन्दर्यं सरसिजभवः स्तौति वदनैः`, `नखेभ्यः सन्त्रस्यन् प्रथममथनादन्धकरिपो`, `श्चतुर्णां शीर्षाणां सममभयहस्तार्पणधिया`], meaning: `Brahma praises, with each of his four mouths, the beauty of your four lotus-stalk-soft, creeper-like arms; yet still fearful of the nails that once tore apart a mighty foe in ancient battle (the attacker's exact identity varies by commentary), he offers, to all four of his own heads equally, the same gesture asking for shelter.` },
  { padas: [`नखानामुद्द्योतैर्नवनलिनरागं विहसतां`, `कराणां ते कान्तिं कथय कथयामः कथमुमे`, `कयाचिद्वा साम्यं भजतु कलया हन्त कमलं`, `यदि क्रीडल्लक्ष्मीचरणतललाक्षारसछणम्`], meaning: `Tell us, Uma, how are we even to speak of the radiance of your hands, whose nails' glow laughs at the fresh red of a newly bloomed lotus? Perhaps the lotus could claim some faint fraction of kinship with them, but only if it had ever had the fortune of being touched by the red lac dye on Lakshmi's own playful feet.` },
  { padas: [`समं देवि स्कन्दद्विपवदनपीतं स्तनयुगं`, `तवेदं नः खेदं हरतु सततं प्रस्नुतमुखम्`, `यदालोक्याशङ्काकुलितहृदयो हासजनकः`, `स्वकुम्भौ हेरम्बः परिमृशति हस्तेन झडिति`], meaning: `May this pair of your breasts, O goddess, nursed equally by Skanda and the elephant-faced one, their tips ever moist, forever take away our sorrow; seeing them, Heramba, his heart uneasy with an amusing suspicion, hastily pats his own twin elephant-temples with his trunk, half in doubt, half in laughter.` },
  { padas: [`अमू ते वक्षोजावमृतरसमाणिक्यकुतुपौ`, `न सन्देहस्पन्दो नगपतिपताके मनसि नः`, `पिबन्तौ तौ यस्मादविदितवधूसङ्गरसिकौ`, `कुमारावद्यापि द्विरदवदनक्रौञ्चदलनौ`], meaning: `We have no flicker of doubt at all, O banner of the mountain-lord's house, that these two breasts of yours are ruby caskets brimming with the taste of nectar - for the two who drank from them, the elephant-faced one and the cleaver of Mount Krauncha, remain to this day untouched by any delight of union with a wife.` },
  { padas: [`वहत्यम्ब स्तम्बेरमदनुजकुम्भप्रकृतिभिः`, `समारब्धां मुक्तामणिभिरमलां हारलतिकाम्`, `कुचाभोगो बिम्बाधररुचिभिरन्तः शबलितां`, `प्रतापव्यामिश्रां पुरदमयितुः कीर्तिमिव ते`], meaning: `You wear, mother, a spotless pearl-string strung from pearls born in the head-bosses of elephants; where it crosses the curve of your breasts, it takes on inner streaks of your lips' bimba-red glow - like the fame of the destroyer of the three cities, itself streaked through with his own martial valor.` },
  { padas: [`तव स्तन्यं मन्ये धरणिधरकन्ये हृदयतः`, `पयःपारावारः परिवहति सारस्वतमिव`, `दयावत्या दत्तं द्रविडशिशुरास्वाद्य तव यत्`, `कवीनां प्रौढानामजनि कमनीयः कवयिता`], meaning: `I think, O daughter of the mountain, that your breast-milk is nothing less than an ocean of Saraswati's own essence flowing straight from your heart; for the Dravidian child who, by your compassion, once tasted what you gave him was, by that alone, made into the most captivating poet among the greatest poets.` },
  { padas: [`हरक्रोधज्वालावलिभिरवलीढेन वपुषा`, `गभीरे ते नाभीसरसि कृतसङ्गो मनसिजः`, `समुत्तस्थौ तस्मादचलतनये धूमलतिका`, `जनस्तां जानीते तव जननि रोमावलिरिति`], meaning: `The faint line of fine hair rising from your navel is said to be smoke: scorched by Shiva's wrathful fire, the love-god Manasija took refuge in the deep pool of your navel, and this trail of smoke from his hiding place is what people call your line of down.` },
  { padas: [`यदेतत्कालिन्दीतनुतरतरङ्गाकृति शिवे`, `कृशे मध्ये किंचिज्जननि तव यद्भाति सुधियाम्`, `विमर्दादन्योन्यं कुचकलशयोरन्तरगतं`, `तनूभूतं व्योम प्रविशदिव नाभिं कुहरिणीम्`], meaning: `O Auspicious One, the delicate marking on your slender waist, like the fine ripples of the Yamuna, appears to the wise as if the space squeezed thin between your two pitcher-like breasts is now entering the deep hollow of your navel.` },
  { padas: [`स्थिरो गङ्गावर्तः स्तनमुकुलरोमावलिलता`, `कलावालं कुण्डं कुसुमशरतेजोहुतभुजः`, `रतेर्लीलागारं किमपि तव नाभिर्गिरिसुते`, `बिलद्वारं सिद्धेगिरिशनयनानां विजयते`], meaning: `O mountain's daughter, your navel triumphs as many things at once: a still whirlpool of the Ganga, the nursery-bed for the creeper-like down rising from your breast-buds, the pit fed by Kama's fiery arrow, Rati's secret bower, and the cave-mouth granting the fulfillment sought by Shiva's gazing eyes.` },
  { padas: [`निसर्गक्षीणस्य स्तनतटभरेण क्लमजुषो`, `नमन्मूर्तेर्नारीतिलक शनकैस्त्रुट्यत इव`, `चिरं ते मध्यस्य त्रुटिततटिनीतीरतरुणा`, `समावस्थास्थेम्नो भवतु कुशलं शैलतनये`], meaning: `O jewel among women, your naturally slender waist, strained further by the weight of your breasts, seems slowly about to give way, like a young tree on a crumbling riverbank; may that precarious balance of yours stay forever safe, O mountain's daughter.` },
  { padas: [`कुचौ सद्यः स्विद्यत्तटघटितकूर्पासभिदुरौ`, `कषन्तौ दोर्मूले कनककलशाभौ कलयता`, `तव त्रातुं भङ्गादलमिति वलग्नं तनुभुवा`, `त्रिधा नद्धं देवि त्रिवलि लवलीवल्लिभिरिव`], meaning: `Your two golden pot-like breasts, straining against the bodice at their base until it seems ready to tear, appear bound by a triple cord in the guise of your waist's three folds, like lavali creepers - as though Kama himself tied them so, to keep them from bursting free.` },
  { padas: [`गुरुत्वं विस्तारं क्षितिधरपतिः पार्वति निजा`, `न्नितम्बादाच्छिद्य त्वयि हरणरूपेण निदधे`, `अतस्ते विस्तीर्णो गुरुरयमशेषां वसुमतीं`, `नितम्बप्राग्भारः स्थगयति लघुत्वं नयति च`], meaning: `O Parvati, your father, the King of Mountains, tore weight and breadth from his own flank and gave them to you as a bridal gift; that is why this vast, heavy mass of your hips now overshadows the whole earth and makes it seem light by comparison.` },
  { padas: [`करीन्द्राणां शुण्डान्कनककदलीकाण्डपटलीम्`, `उभाभ्यामूरुभ्यामुभयमपि निर्जित्य भवती`, `सुवृत्ताभ्यां पत्युः प्रणतिकठिनाभ्यां गिरिसुते`, `विधिज्ञ्ये जानुभ्यां विबुधकरिकुम्भद्वयमसि`], meaning: `Having conquered, with your two thighs alone, both the trunks of great elephants and clusters of golden banana stems, O knower of due order, your two knees - rounded and hardened by countless bows to your husband - now match the twin frontal domes of the celestial elephant.` },
  { padas: [`पराजेतुं रुद्रं द्विगुणशरगर्भौ गिरिसुते`, `निषङ्गौ जङ्घे ते विषमविशिखो बाढमकृत`, `यदग्रे दृश्यन्ते दशशरफलाः पादयुगली`, `नखाग्रच्छद्मानः सुरमकुटशाणैकनिशिताः`], meaning: `O mountain's daughter, to help him conquer Rudra, Kama turned your two shins into a pair of quivers each holding double the usual arrows - for at their tip may be seen ten arrow-heads, which are in truth your toenails, sharpened uniquely on the touchstone of the gods' bowed crowns.` },
  { padas: [`श्रुतीनां मूर्धानो दधति तव यौ शेखरतया`, `ममाप्येतौ मातः शिरसि दयया धेहि चरणौ`, `ययोः पाद्यं पाथः पशुपतिजटाजूटतटिनी`, `ययोर्लाक्षालक्ष्मीररुणहरिचूडामणिरुचिः`], meaning: `O Mother, mercifully place on my head too those same two feet that even the crowning Upanishads wear as their own diadem - feet whose washing-water became the Ganga caught in Pashupati's matted hair, and whose red lac-glow rivals the ruby in Vishnu's crest jewel.` },
  { padas: [`नमोवाकं ब्रूमो नयनरमणीयाय पदयोः`, `तवास्मै द्वन्द्वाय स्फुटरुचिरसालक्तकवते`, `असूयत्यत्यन्तं यदभिहननाय स्पृहयते`, `पशूनामीशानः प्रमदवनकङ्केलितरवे`], meaning: `We bow to this pair of your feet, delightful to the eyes and bright with red lac-dye - feet that even Ishana, lord of all creatures, envies intensely, since he himself longs to strike the flowering ashoka tree in the pleasure-grove with just such a touch.` },
  { padas: [`मृषा कृत्वा गोत्रस्खलनमथ वैलक्ष्यनमितं`, `ललाटे भर्तारं चरणकमले ताडयति ते`, `चिरादन्तःशल्यं दहनकृतमुन्मूलितवता`, `तुलाकोटिक्वाणैः किलिकिलितमीशानरिपुणा`], meaning: `Feigning a slip of the tongue and then bowing his head low in mock shame, Shiva lets your lotus foot strike his forehead - a playful blow ringing out like the clink of scale-weights, delighting the very foe of Kama, who long ago had already burned out that old thorn of grief. (Rendered with moderate confidence; this playful verse rests on a specific narrative reading of a lovers' tease.)` },
  { padas: [`हिमानीहन्तव्यं हिमगिरिनिवासैकचतुरौ`, `निशायां निद्राणं निशि चरमभागे च विशदौ`, `वरं लक्ष्मीपात्रं श्रियमतिसृजन्तौ समयिनां`, `सरोजं त्वत्पादौ जननि जयतश्चित्रमिह किम्`], meaning: `Your two feet, uniquely able to dwell on the snow peaks and dispel their frost, resting through the night yet radiant again in its last watch, ceaselessly grant supreme fortune to the faithful - small wonder, then, that they triumph even over the lotus, which shuts at night and cannot bear the cold at all.` },
  { padas: [`पदं ते कीर्तीनां प्रपदमपदं देवि विपदां`, `कथं नीतं सद्भिः कठिनकमठीकर्परतुलाम्`, `कथं वा बाहुभ्यामुपयमनकाले पुरभिदा`, `यदादाय न्यस्तं दृषदि दयमानेन मनसा`], meaning: `O Devi, how could the wise ever compare your foot - the very seat of fame and remover of misfortune - to the hard, rough shell of a tortoise? And how, at your wedding, could Shiva, destroyer of the triple city, bear to press that same tender foot upon a rough stone, however gently and with whatever compassion?` },
  { padas: [`नखैर्नाकस्त्रीणां करकमलसंकोचशशिभिः`, `तरूणां दिव्यानां हसत इव ते चण्डि चरणौ`, `फलानि स्वःस्थेभ्यः किसलयकराग्रेण ददतां`, `दरिद्रेभ्यो भद्रां श्रियमनिशमह्नाय ददतौ`], meaning: `O fierce one, your two feet, whose toenails outshine the moon and shame the cupped lotus-hands of heavenly women, seem to mock the wish-granting trees of paradise - for those trees give fruit only to those already in heaven, while your feet freely grant good fortune even to the poor.` },
  { padas: [`ददाने दीनेभ्यः श्रियमनिशमाशानुसदृशी`, `ममन्दं सौन्दर्यप्रकरमकरन्दं विकिरति`, `तवास्मिन्मन्दारस्तबकसुभगे यातु चरणे`, `निमज्जन्मज्जीवः करणचरणः षट्चरणताम्`], meaning: `May my sinking, restless life-breath, with all its senses, become like a bee settling forever at this foot of yours - lovely as a cluster of mandara blossoms - a foot that ceaselessly showers boundless, nectar-like beauty and grants fortune to the destitute beyond their own hope.` },
  { padas: [`पदन्यासक्रीडापरिचयमिवारब्धुमनसः`, `स्खलन्तस्ते खेलं भवनकलहंसा न जहति`, `अतस्तेषां शिक्षां सुभगमणिमञ्जीररणित`, `च्छलादाचक्षाणं चरणकमलं चारुचरिते`], meaning: `O one of lovely conduct, the very swans of your household keep faltering as they try again and again to master the playful art of your walk, yet never give up; it is as if your lotus foot, through the pretext of its jewelled anklets' jingling, is patiently teaching them how to walk.` },
  { padas: [`गतास्ते मञ्चत्वं द्रुहिणहरिरुद्रेश्वरभृतः`, `शिवः स्वच्छच्छायाघटितकपटप्रच्छदपटः`, `त्वदीयानां भासां प्रतिफलनरागारुणतया`, `शरीरी शृङ्गारो रस इव दृशां दोग्धि कुतुकम्`], meaning: `Brahma, Vishnu, Rudra and Ishvara have become the frame of a couch, and Shiva's own pure, translucent radiance its deceptive white coverlet; reddened by the reflected glow of your body's luster, that couch delights the eye as though the erotic sentiment itself had taken visible form.` },
  { padas: [`अराला केशेषु प्रकृतिसरला मन्दहसिते`, `शिरीषाभा चित्ते दृषदुपलशोभा कुचतटे`, `भृशं तन्वी मध्ये पृथुरुरसिजारोहविषये`, `जगत्त्रातुं शंभोर्जयति करुणा काचिदरुणा`], meaning: `Curling in your tresses yet naturally gentle in your soft smile, delicate as a shirisha blossom at heart yet firm as polished stone at your breasts, slender at the waist yet ample at your rising bosom - some indescribable, rose-tinted compassion of Shiva, taking your form, triumphs to protect the world.` },
  { padas: [`कलङ्कः कस्तूरी रजनिकरबिम्बं जलमयं`, `कलाभिः कर्पूरैर्मरकतकरण्डं निबिडितम्`, `अतस्त्वद्भोगेन प्रतिदिनमिदं रिक्तकुहरं`, `विधिर्भूयो भूयो निबिडयति नूनं तव कृते`], meaning: `The dark mark on the moon is musk, its watery orb is camphor, and its phases are what pack this emerald casket full; since you empty this hollow daily by using it as your own cosmetic, Brahma must surely be refilling it again and again, purely for your sake.` },
  { padas: [`पुरारातेरन्तःपुरमसि ततस्त्वच्चरणयोः`, `सपर्यामर्यादा तरलकरणानामसुलभा`, `तथा ह्येते नीताः शतमखमुखाः सिद्धिमतुलां`, `तव द्वारोपान्तस्थितिभिरणिमाद्याभिरमराः`], meaning: `You are the very inner sanctum of Shiva, foe of the Tripura demons; the privilege of worshipping your feet is therefore not easily won by the restless senses - indeed, merely by standing near your doorway did Indra and the other gods attain their matchless powers, such as the power to become minute.` },
  { padas: [`कलत्रं वैधात्रं कतिकति भजन्ते न कवयः`, `श्रियो देव्याः को वा न भवति पतिः कैरपि धनैः`, `महादेवं हित्वा तव सति सतीनामचरमे`, `कुचाभ्यामासङ्गः कुरवकतरोरप्यसुलभः`], meaning: `What poet does not court Sarasvati, Brahma's consort? And who, with enough wealth, does not become some sort of lord to Lakshmi? Yet you, O most faithful of wives, grant the embrace of your bosom to none but Mahadeva alone - a closeness even the kuravaka tree, said to crave a woman's touch, can never attain.` },
  { padas: [`गिरामाहुर्देवीं द्रुहिणगृहिणीमागमविदो`, `हरेः पत्नीं पद्मां हरसहचरीमद्रितनयाम्`, `तुरीया कापि त्वं दुरधिगमनिःसीममहिमा`, `महामाया विश्वं भ्रमयसि परब्रह्ममहिषि`], meaning: `Knowers of scripture call you Sarasvati, Brahma's consort; they call you Padma, Vishnu's wife; they call you Parvati, Shiva's companion - yet you, O queen of the Supreme Brahman, are some indescribable fourth reality of boundless glory, the great cosmic illusion that sets the whole universe spinning.` },
  { padas: [`कदा काले मातः कथय कलितालक्तकरसं`, `पिबेयं विद्यार्थी तव चरणनिर्णेजनजलम्`, `प्रकृत्या मूकानामपि च कविताकारणतया`, `कदा धत्ते वाणीमुखकमलताम्बूलरसताम्`], meaning: `Tell me, Mother, when will the day come when I, a seeker of knowledge, may drink the lac-tinted water that has washed your feet - water which awakens poetry even in those naturally mute, and which one day will lend even Sarasvati's own lotus-mouth the flavor of betel leaf?` },
  { padas: [`सरस्वत्या लक्ष्म्या विधिहरिसपत्नो विहरते`, `रतेः पातिव्रत्यं शिथिलयति रम्येण वपुषा`, `चिरं जीवन्नेव क्षपितपशुपाशव्यतिकरः`, `परानन्दाभिख्यं रसयति रसं त्वद्भजनवान्`], meaning: `One devoted to you lives as though a rival even to Brahma and Vishnu, favored equally by Sarasvati and Lakshmi; with his own charming form he unsettles even Rati's devotion to her husband, and living long while shedding every bond of worldly existence, he alone savors the true flavor called supreme bliss.` },
  { padas: [`प्रदीपज्वालाभिर्दिवसकरनीराजनविधिः`, `सुधासूतेश्चन्द्रोपलजललवैरर्घ्यरचना`, `स्वकीयैरम्भोभिः सलिलनिधिसौहित्यकरणं`, `त्वदीयाभिर्वाग्भिस्तव जननि वाचां स्तुतिरियम्`], meaning: `Just as waving lamp-flames before the sun, offering the moon water drawn from its own moonstone, or trying to fill the ocean with its own waters would all be pointless, so too, O Mother, is this hymn composed from words that are themselves your own gift - yet I offer it all the same.` },
];

if (VERSES.length !== 100) throw new Error(`Expected 100 verses, got ${VERSES.length}`);
VERSES.forEach((v, i) => {
  if (v.padas.length !== 4) throw new Error(`Verse ${i + 1}: expected 4 padas, got ${v.padas.length}`);
});
console.log('Structure check passed: 100 verses, 4 padas each.\n');

function addMacrons(iast) {
  return iast.replace(/e/g, 'ē').replace(/o/g, 'ō');
}

const DEV_DIGITS = '०१२३४५६७८९';
function toDevNumeral(n) {
  return String(n).split('').map(d => DEV_DIGITS[+d]).join('');
}

const rows = VERSES.map((v, i) => {
  const stanzaNumber = i + 1;
  const devaPadas = [...v.padas];
  devaPadas[1] += ' ।'; // danda after pada 2
  devaPadas[3] += ` ॥${toDevNumeral(stanzaNumber)}॥`; // full-verse marker after pada 4

  return {
    stanza_number: stanzaNumber,
    stanza_label: `Ślōka ${stanzaNumber}`,
    script_devanagari: devaPadas.join('|'),
    script_telugu: v.padas.map(p => Sanscript.t(p, 'devanagari', 'telugu')).join('|'),
    script_tamil: v.padas.map(p => devanagariToTamilSuperscript(p)).join('|'),
    roman_iast: v.padas.map(p => addMacrons(Sanscript.t(p, 'devanagari', 'iast'))).join('|'),
    meaning_en: v.meaning,
  };
});

console.log('Sample (verses 1, 41, 42, 100):\n');
[0, 40, 41, 99].forEach(i => console.log(rows[i], '\n'));

const auth = new google.auth.GoogleAuth({
  credentials: JSON.parse(process.env.GOOGLE_SERVICE_ACCOUNT_KEY),
  scopes: ['https://www.googleapis.com/auth/spreadsheets'],
});
const client = await auth.getClient();
const sheets = google.sheets({ version: 'v4', auth: client });

const res = await sheets.spreadsheets.values.get({ spreadsheetId: process.env.SHEETS_SPREADSHEET_ID, range: 'shloka_stanzas!A:A' });
const existingCount = (res.data.values || []).slice(1).filter(r => r[0] === SLUG).length;
console.log(`Existing shloka_stanzas rows for "${SLUG}": ${existingCount}`);

if (!WRITE) {
  console.log('\nDry run only — no changes written. Re-run with --write to apply.');
} else {
  if (existingCount > 0) {
    console.error(`Refusing to append: ${existingCount} rows already exist for "${SLUG}". This script only handles the pure-append (0 existing rows) case.`);
    process.exit(1);
  }
  const appendRows = rows.map(r => [
    SLUG, r.stanza_number, r.stanza_label, r.script_devanagari, r.script_telugu, r.script_tamil, r.roman_iast,
    r.meaning_en, '', '', '', '',
  ]);
  await sheets.spreadsheets.values.append({
    spreadsheetId: process.env.SHEETS_SPREADSHEET_ID,
    range: 'shloka_stanzas!A1',
    valueInputOption: 'RAW',
    requestBody: { values: appendRows },
  });
  console.log(`Appended ${appendRows.length} rows for "${SLUG}".`);
}
